import {ecosystem} from './ecosystem.js';
// Source-based editorial research. Project statements are not independent audits.
const entry=(privacy,limits,security,goal,next,sources,status='Project documentation reviewed')=>({privacy,limits,security,goal,next,sources,status});
export const research={
monero:entry('Stealth addresses provide one-time destinations; RingCT hides amounts; ring signatures obscure which candidate output was spent. These protections apply to normal native transfers without a transparent payment mode.','A payment counterparty still knows its own payment. Timing, exchange records, compromised devices and network observations can connect activity to a person. Decoy selection is a separate privacy assumption.','Proof-of-work consensus and transaction validation protect ledger integrity; they do not protect stolen wallet keys. Privacy research and independent implementation review remain important even with mandatory privacy.','Make fungible, permissionless digital cash practical while keeping ordinary users private by default.','FCMP++ research aims to replace small ring-based candidate sets with much broader membership proofs. The May 2026 project update did not set an activation date; this review does not certify activation. Wallet integration, review and network coordination are delivery dependencies.',['https://www.getmonero.org/get-started/faq/','https://www.getmonero.org/2024/04/27/fcmps.html','https://www.getmonero.org/2026/05/10/deprecating-unlock-time.html']),
zcash:entry('Shielded transfers prove validity without publishing the protected sender, recipient or amount. Zcash also supports transparent activity, so protection depends on the wallet, pool and complete payment path.','Entering or leaving shielding can expose amounts and timing. Transparent addresses remain public. Sharing viewing information or using an identifiable service changes who can see activity.','Proof-system security, consensus implementation and wallet correctness are distinct requirements. A proof hiding payment details does not prevent phishing or endpoint compromise.','Make encrypted electronic cash usable at much greater scale, with practical wallets and private payments.','Project Tachyon is a proposed scalability redesign aimed at smaller transactions and limiting validator state growth. Its developers also describe post-quantum privacy benefits. It requires community approval and activation; those proposed properties must not be attributed to every current Zcash transfer.',['https://z.cash/learn/what-is-the-difference-between-shielded-and-transparent-zcash/','https://tachyon.z.cash/']),
zano:entry('The documentation describes default concealment of addresses, amounts and asset types. Confidential assets extend that model beyond ZANO, and private staking is part of the design.','Confidential tokens do not make their issuer trustworthy. A bridge, exchange, application or payment counterparty can retain identifying information outside the chain.','Zano combines proof of work and proof of stake. Consensus participation, wallet implementation and the private staking construction each introduce assumptions; staking rewards are not evidence of security.','Provide a base layer for confidential payments, privately issued assets and financial applications.','The ecosystem direction is broader wallet and application integration around confidential assets. Current documentation includes issuance and integration tooling; this review does not establish a dated delivery schedule for additional products.',['https://docs.zano.org/']),
'pirate-chain':entry('Normal peer-to-peer ARRR transfers use mandatory shielded zero-knowledge transactions. This avoids a user-selectable transparent payment path for ordinary transfers.','Shielding does not hide every network connection or information given to a merchant. Wrapped ARRR and external trading venues have separate privacy and custody properties.','Proof of work is supplemented by delayed-proof-of-work notarization. This adds dependencies on the notarization system; it is not immunity from every attack. Proof-system transitions require coordinated software upgrades.','Expand practical private cash through easier wallets, payment acceptance and a stronger shielded protocol.','The September 8, 2026 update targets an Ironwood transition and dPoW update for October 3 and reports Stashi wallet and lightwallet privacy improvements. Older site notices give a different deadline, so the current release instructions must govern upgrade decisions. The future fork is not treated as already activated.',['https://piratechain.com/','https://piratechain.com/blog/pirate-chain-monthly-update-september-2026/']),
zcoin:entry('Lelantus Spark is designed to hide sender, recipient and amount without a trusted setup. Privacy depends on using Spark rather than assuming every supported transaction path is shielded.','Transparent entry and exit, payment metadata and wallet behavior remain relevant. Confidentiality cannot prevent a recipient from disclosing information about its own payment.','The privacy proof and the chain’s consensus security are separate. Removing a trusted setup removes one assumption, but still leaves cryptographic, implementation and upgrade risks.','Combine private cash with easier addressing, confidential asset issuance and private exchange.','The published roadmap lists view-key tooling and private mining rewards, then Spark Assets, Spark Swap and Curve Trees. Longer-term research includes quantum resistance, light wallets and governance. These are roadmap categories, not verified completion claims or guaranteed dates.',['https://firo.org/pillars/private/','https://firo.org/about/roadmap/']),
minotari:entry('Tari’s base layer uses Mimblewimble-style confidential transactions. Ootle is a separate application layer: resource confidentiality and what a contract exposes must be assessed per application.','Hidden amounts do not establish complete transaction-graph anonymity. An application can publish state or collect personal details. Wrapped XTM inherits bridge and host-chain exposure.','Base-layer proof of work, Ootle validators, application authorization and bridge custody are different security boundaries. A secure base chain does not establish that an escrow contract or frontend is safe.','Support programmable privacy: developers create assets and applications while users retain control over what is disclosed.','The September 1, 2026 announcement targets Ootle for November 11, with developer events and a community-led council and contributor program. This is a published launch target, not confirmation of delivery. Adoption also depends on usable wallets, application quality and developer participation.',['https://rfc.tari.com/','https://ootle.tari.com/','https://tari.com/updates/2026-09-01-update-143']),
decred:entry('Privacy tooling mixes outputs on a transparent ledger to make direct ownership links harder to follow. It does not encrypt all ledger amounts or erase transaction history.','Timing, recognizable amounts and later consolidation can undermine mixing. Network anonymity and protection from a payment counterparty are separate from output mixing.','Hybrid proof-of-work and stakeholder voting contribute to consensus. Governance does not guarantee that software has no vulnerabilities; a mixed output remains subject to ordinary key security.','Sustain digital money through stakeholder governance, funded development and practical user sovereignty.','Future direction centers on improving the currency and its ecosystem through stakeholder proposals. A proposal or treasury vote is not a delivered feature; no new dated privacy upgrade is certified by this review.',['https://docs.decred.org/privacy/general-privacy/','https://decred.org/']),
dash:entry('CoinJoin groups and mixes standardized outputs to obscure direct ownership links. Ordinary addresses, transactions and amounts remain visible on the public chain.','Mixing can be weakened by later spending patterns, change outputs and external records. InstantSend is a confirmation feature, not transaction encryption.','Proof of work and masternode services have different roles. Masternode-assisted functions introduce their own operational and quorum assumptions; none eliminates wallet-key risk.','Make digital payments fast and usable, while expanding application infrastructure and community governance.','The strategic direction includes payment adoption and Dash application services. Existing InstantSend and CoinJoin features are not presented as future milestones; completion dates for further privacy improvements were not established in this review.',['https://docs.dash.org/en/stable/docs/user/introduction/features.html']),
beam:entry('Beam combines Mimblewimble and Lelantus-based protections. Amounts are confidential, and confidential assets and different transaction modes extend the available privacy model.','Privacy varies with transaction construction and use of the available anonymity options. Smart-contract behavior, bridges and disclosed application data require separate analysis.','Proof of work secures ordering; range proofs and contract logic protect different properties. A contract flaw or bridge compromise can matter even when transfers remain confidential.','Build confidential finance with assets, swaps and applications supported by the Beam Virtual Machine.','The project describes further lending, oracle, sidechain and wrapped-asset functionality alongside its existing wallet and DeFi tools. These ambitions depend on implementation review, integrations and usage; a feature on a vision page is not a verified launch.',['https://www.beam.mw/']),
grin:entry('Mimblewimble hides amounts and avoids conventional on-chain addresses. Aggregation and cut-through reduce retained transaction data; staged relay aims to make transaction origin harder to observe.','An observer watching transactions before aggregation may infer links. Hidden amounts and compressed history do not imply that every transaction relationship is unobservable.','Proof-of-work security, cryptographic commitments and wallet transaction construction are separate dependencies. The project identifies itself as experimental.','Maintain simple, open, censorship-resistant electronic cash intended for long-term use.','The emphasis is ongoing protocol, wallet and research work supported by a volunteer community and donations. This is a durable currency mission, not a promised sequence of new financial products; this review establishes no fixed milestone dates.',['https://grin.mw/']),
'zephyr-protocol':entry('Zephyr combines Monero-derived payment privacy with a reserve-backed stablecoin system. Private transfers and the stability mechanism solve different problems.','Transaction context around minting and redemption can add information. Privacy does not establish that a stablecoin will hold its peg or that redemptions will always be available.','Consensus and wallet security sit alongside collateral, pricing and reserve-management risks. ZEPH is the volatile reserve asset, not the dollar-pegged asset.','Offer private stable-value transactions backed by an overcollateralized crypto reserve.','The long-term objective is useful private stablecoin payments and sustainable reserves. Assess future expansion through published releases and reserve rules; this review does not establish a dated new-product rollout.',['https://zephyrprotocol.com/']),
dero:entry('DERO describes an account-based system using homomorphic encryption for private balances and transfers, with support for smart contracts.','A private transfer system does not imply that every contract variable, application event or interaction is secret. The actual application interface and disclosed data matter.','Encryption, proof verification, consensus and contract code each need review. Wallet compromise can reveal secrets without breaking the underlying cryptography.','Provide a platform for private digital cash and decentralized services with programmable logic.','Its direction is application development around the documented contract platform and wallet tooling. This review does not verify a new dated roadmap; distinguish supported examples from a mature, audited application ecosystem.',['https://docs.dero.io/']),
pivx:entry('SHIELD provides optional zero-knowledge transaction privacy on a proof-of-stake chain. Users must distinguish shielded activity from transparent transfers and staking-related activity.','Movement between private and public use can expose context. Wallet support and user choices determine the protection actually obtained.','Stake distribution, consensus implementation and shielded proof verification are separate dependencies. Delegating or operating staking infrastructure introduces additional operational considerations.','Combine digital cash, optional confidentiality, staking and community-funded development.','The continuing direction is usability and adoption of private payments within its staking ecosystem. A specific future release date is not established here; roadmap claims require matching wallet releases and network activation.',['https://pivx.org/']),
xelis:entry('Homomorphic encryption protects balances and transferred asset values while allowing computation on encrypted values. The documentation also covers confidential assets and zero-knowledge proofs.','Encrypted amounts are not proof that sender and recipient relationships are unlinkable. Public application interactions and network metadata require their own privacy analysis.','The BlockDAG consensus, encrypted-balance implementation and smart-contract permissions are distinct security surfaces. Contract integrations must not inherit a blanket security claim from the currency.','Combine confidential value transfers with programmable assets and applications.','Documentation now includes the XVM/Silex contract environment and developer APIs. The forward objective is useful applications and integrations; the existence of documentation is not evidence that every proposed application is delivered or audited.',['https://docs.xelis.io/features/privacy/homomorphic-encryption','https://docs.xelis.io/']),
nockchain:entry('Nockchain uses proof-oriented computation, but zero-knowledge proof infrastructure does not automatically make base-layer transfers private. Its published roadmap places privacy in a future application layer.','Do not treat current NOCK transfers as shielded solely because the project uses ZK terminology. Bridges and future privacy-pool entry and exit will have separate exposure.','Proof verification, proof-of-work consensus and future application logic must be evaluated independently. Bridge custody is another security boundary.','Build programmable money and markets for verifiable computation, with private applications on top.','The roadmap lists a privacy-pool app for Q2 2027, preceded by proof verification and forced data availability, and later private DeFi foundations and post-quantum signatures. These are project targets. None is counted here as an already-active privacy guarantee.',['https://www.nockchain.org/','https://www.nockchain.org/roadmap']),
'neptune-cash':entry('The project documents zk-STARKs, client-side proving and mutator sets to support private transactions and compact verification. It describes programmable transaction logic.','Novel privacy constructions still need implementation scrutiny. A claim of post-quantum design does not establish that endpoints, bridges or every third-party application share that property.','The proof system, mutator-set implementation and proof-of-work consensus are distinct dependencies. This review has not independently audited them.','Combine private digital cash, programmable transactions and a cryptographic design intended to resist quantum attacks.','The stated direction is a private application platform with compact validation and community maintenance. No new dated feature commitment is verified here. This asset is distinct from Neptune Privacy at neptune.io.',['https://neptune.cash/']),
'neptune-privacy':entry('Neptune Privacy describes a privacy-focused base network and a Miden-based zk-STARK execution layer for private smart contracts. These are project descriptions, not an independent confirmation of deployment.','The exact protection of the traded asset and each application must be established separately. Quantum-safe marketing is not proof that every component resists quantum attacks.','Consensus, execution proofs, any bridge and wallet implementations each need review. Deployment state and audit coverage have not been independently established here.','Develop private digital cash and scalable private applications, including DeFi.','The site describes its execution-layer and developer ecosystem ambitions. Treat functionality without verifiable releases as a claim, not a delivered milestone. Neptune Privacy is not Neptune Cash; their documentation and security assumptions must not be combined.',['https://neptune.io/'],'Project claims reviewed; deployment not independently verified'),
ycash:entry('Ycash provides shielded transaction support alongside its digital-cash network. The selected transfer path matters; a shielded-capable asset is not the same as an entirely shielded payment history.','Public transfers, shielding boundaries and third-party records can reveal context. Wrapped Ycash has separate host-chain and bridge properties.','Wallet correctness, proof verification and mining security matter separately. Shared ancestry with another chain does not prove identical current safeguards.','Empower local and online communities with accessible digital cash and permissionless participation.','Its stated direction emphasizes payments, wallets and community use. The reviewed site provides wallet and developer resources but does not establish a dated new privacy milestone.',['https://y.cash/']),
'epic-cash':entry('Epic describes Mimblewimble-based transfers with hidden amounts and no conventional stored ledger addresses, plus multi-algorithm proof-of-work mining.','Aggregation is not proof of complete resistance to a live network observer. Project claims of absolute privacy should not be interpreted as guarantees.','Mining distribution and cryptographic implementation require separate analysis. Multiple algorithms alone do not establish immunity from majority attacks.','Become widely usable peer-to-peer electronic cash for ordinary payments.','The project emphasizes easier wallet access, broad participation and payment adoption. Claims about very large future throughput are ambitions, not independently verified capacity in this review. No firm new-feature date is established here.',['https://epic.tech/']),
particl:entry('Particl positions its currency and decentralized marketplace around financial privacy and peer-to-peer interaction. Currency privacy and marketplace confidentiality are separate layers.','A merchant can learn shipping details even when payment details are protected. Listings, messages, escrow rules and external swaps may reveal information beyond the payment ledger.','Marketplace software, escrow behavior, wallets and swap protocols need their own security review. The project’s privacy language does not establish that every application is audited.','Provide applications that reduce reliance on intermediaries, including a marketplace and decentralized exchange tools.','The forward direction is adoption and improvement of the marketplace, currency and BasicSwap ecosystem. The reviewed overview does not provide verified completion dates for additional features.',['https://particl.io/']),
zclassic:entry('Zclassic is a Zcash-derived project associated with shielded transaction technology. Its current privacy coverage must be checked against its own releases rather than newer Zcash upgrades.','Do not assume Orchard, Tachyon or any other Zcash development automatically applies to Zclassic. Transparent activity and shielding boundaries remain separate considerations.','A fork inherits historical code, not a perpetual stream of upstream fixes. Current maintenance, wallet support and network security need project-specific verification.','Maintain an independent digital-cash network following its own funding and protocol choices.','The reviewed project site does not establish a current dated roadmap for major new privacy features. New milestones should be assessed against signed releases and activation details rather than the parent project’s roadmap.',['https://zclassic.org/'],'Limited current technical evidence'),
nerva:entry('Nerva uses Monero-derived privacy technology and emphasizes solo CPU mining. Its own releases determine which privacy improvements are active.','Monero ancestry does not mean feature parity. Decoy selection, output rules, timing and endpoint metadata can affect practical privacy.','Pool resistance is a design goal, not proof of evenly distributed hashpower. Consensus changes and ported upstream fixes still require implementation review.','Keep private cash accessible to ordinary CPU miners while narrowing the technical gap with Monero.','The project describes Hard Fork 14 work on CLSAG, Bulletproofs+ and a larger ring size, with a possible mining-algorithm revision. The reviewed update gives no activation height; planned changes are not counted as live.',['https://nerva.one/']),
ryo:entry('Ryo describes RingCT with a ring size of 25 to obscure amounts and spending relationships. Its project materials also discuss transaction-analysis limitations.','A larger ring is not a guarantee of anonymity: decoy quality, output merging and external metadata still matter. Network privacy is a separate concern.','Cryptographic implementation and mining security require review independently of the advertised ring size. A planned proof-system migration is not an existing safeguard.','Provide private payments while pursuing stronger protections against transaction tracing.','The project advertises a future migration to zero-knowledge proofs. This review does not establish activation or a reliable delivery date, so the prospective design is kept separate from the described RingCT system.',['https://ryo-currency.com/']),
karbo:entry('Karbo describes a CryptoNote-based privacy currency, with its current site emphasizing decentralized participation and direct user control. The precise current amount-hiding guarantees are not established by that overview.','CryptoNote branding alone does not prove RingCT support or equivalence to current Monero. Wallet and network metadata can remain informative.','The site describes signed proof of work and solo CPU mining to discourage pooling. Its effectiveness and implementation have not been independently audited here.','Preserve private peer-to-peer cash and egalitarian mining rather than prioritize a fixed product roadmap.','The published direction emphasizes solo mining, wallets, node tools and integration support. It explicitly puts design principles ahead of specific roadmap promises; no dated new privacy upgrade is asserted here.',['https://karbo.org/'],'Project overview reviewed; protocol coverage incomplete'),
salvium:entry('Salvium describes confidential transactions alongside refundable transfers, view keys and spend-authority proofs. These features are intended to support controlled disclosure and integration.','Selective disclosure changes who can inspect activity. A project’s compliance positioning is not a legal determination or proof of universal exchange acceptance.','Transaction proofs, refund semantics and future contract execution need separate security analysis. Confidentiality does not establish the safety of a DeFi application.','Extend private transfers into programmable finance, including contracts and stablecoin use cases.','The project describes private smart-contract capabilities and middleware for porting Ethereum applications as development goals. Those ambitions must be distinguished from current cash-transfer functions and independently verified deployment.',['https://salvium.io/']),
stellite:entry('Scala presents a privacy-oriented, mobile-friendly cryptocurrency and wallet ecosystem. Its overview emphasizes accessible mining and anonymous transfers.','Mobile usability does not remove device, wallet-server or network metadata risks. This review does not establish the exact current anonymity set or all amount-hiding properties.','Mobile mining and wallets broaden the endpoint surface. Network consensus and the safety of individual Android applications must be assessed separately.','Make private digital cash and participation accessible on ordinary and mobile hardware.','The direction is accessible wallets, mining and ecosystem tools. A dated future protocol milestone was not established from the reviewed overview.',['https://scala.network/'],'Project overview reviewed; protocol coverage incomplete'),
kryptokrona:entry('Kryptokrona combines a payment network with Hugin, an encrypted peer-to-peer messenger. Messaging confidentiality and native-payment privacy are different properties.','Encrypted message content does not establish that all metadata is hidden. This review does not verify complete sender, recipient and amount concealment for every XKR transfer.','The currency node, wallet and messaging client have separate attack surfaces. Endpoint compromise can bypass message encryption without breaking it.','Develop open payment and communication tools, originally framed as a Nordic alternative for a cashless society.','The published ecosystem includes Hugin desktop/mobile software, wallets and explorer tools. Its continuing objective is broader secure communication and payment use; no dated additional milestone is certified here.',['https://kryptokrona.org/'],'Project overview reviewed; protocol coverage incomplete'),
hush:entry('Hush presents shielded payments and encrypted communication through its privacy-focused ecosystem. Payment confidentiality and messaging protections should be evaluated separately.','Message recipients, wallet endpoints and network observations can still reveal information. Shielded transaction claims do not establish perfect communication anonymity.','Node software, proof verification and messaging clients all require maintenance. A shared cryptographic family does not establish that upstream fixes or upgrades have been adopted.','Support private communication as well as private digital payments.','The strategic direction is the Hush and SilentDragon ecosystem. This review establishes the project’s objective but not a dated new protocol rollout or independently audited completion of every advertised capability.',['https://hush.is/']),
bytecoin:entry('Bytecoin identifies itself as a CryptoNote cryptocurrency designed for anonymous transfers. Its historical design should be assessed on its own current implementation.','CryptoNote does not by itself establish modern confidential amounts or equivalence to current Monero. Decoys, wallet behavior and network observations remain important.','Current maintenance and mining distribution matter independently of the age of the project. Historical innovation does not establish that present software is fully patched.','Provide private, decentralized electronic payments.','The reviewed overview supports that broad purpose but does not establish a reliable current schedule for major privacy upgrades. New development claims require current releases and protocol documentation.',['https://bytecoin.org/'],'Limited current technical evidence'),
spectrecoin:entry('Alias, formerly Spectrecoin, promotes private digital cash and private staking through its wallet ecosystem. These are project claims; the full transaction model was not independently audited here.','Private staking, private transfers and IP protection are separate properties. The protection obtained depends on the wallet and transaction mode.','Proof-of-stake participation and wallet implementation remain security dependencies. An advertised private staking wallet is not proof of safe custody or flawless consensus.','Make private cash and staking practical on desktop and mobile.','Its site links development, community and adoption plans and promotes a mobile staking wallet. This review does not establish dates or completion status for additional roadmap items.',['https://alias.cash/'],'Project overview reviewed; protocol coverage incomplete'),
'xeqm-labs':entry('Exiom describes programmable privacy for identity, data, communications and access control on a proof-of-stake platform. These application claims are broader than ordinary coin-transfer privacy.','An API or identity service can have different disclosure and trust assumptions from the base ledger. A privacy-themed platform does not establish anonymous native transfers.','Validator distribution, API operators, application authorization and cryptography must be assessed independently. Deployment and audit coverage are not independently certified here.','Offer developers privacy services for credentials, data feeds, communications and governance.','The site describes a developer platform with staking-based API access and application integration. This is a project-stated direction; there is no independently verified delivery timetable for its full application vision in this review.',['https://xeqmlabs.com/'],'Project claims reviewed; deployment not independently verified'),
maryjanecoin:entry('The site describes a native proof-of-stake chain with stealth addresses and denomination-based mixing, plus a separate Solana token connected by a bridge.','Denomination mixing is not the same as cryptographically hidden amounts. Solana token transfers and bridge records must not inherit native-chain privacy claims.','The native chain, bridge and Solana token have distinct risks. Claims of atomic bridging and statistical untraceability have not been independently validated here.','Combine token access on Solana with a native privacy-oriented spending network.','The site describes wallet, bridge and payment infrastructure. This review does not establish a dated next release or independently verify the advertised deployment claims; the native and token representations must be distinguished.',['https://maryjanecoin.net/'],'Project claims reviewed; deployment not independently verified'),
};

// Limited-evidence records retain explicit identity and gaps rather than borrowing
// similarly named projects' technical details or inventing a roadmap.
const gaps={
verge:['Network privacy and ledger confidentiality need separate assessment; the reviewed current homepage did not expose sufficient technical detail to certify either.','The project describes accessible everyday blockchain payments; a dated future privacy milestone was not verified.',['https://vergecurrency.com/']],
'nav-coin':['The current Navio description claims hidden senders, recipients and amounts. Migration state and the exact protection of the asset listed as nav-coin were not verified.','The stated direction is private internet money. Current Navio claims should not be automatically assigned to a legacy NavCoin wallet or chain.',['https://nav.io/']],
bitcoinz:['The project presents community-run digital currency. Current shielded-transfer availability and wallet defaults were not fully established in this review.','The stated direction emphasizes community participation and payments. No verified dated privacy upgrade is established here.',['https://getbtcz.com/']],
conceal:['The project describes private finance and encrypted communications, but current technical documentation could not be sufficiently reviewed to certify the transfer model.','Private finance and communication are the stated direction. Current deliverables and future milestone dates remain unverified.',['https://conceal.network/']],
'mimblewimblecoin':['The project identifies a Mimblewimble design. Exact current wallet modes and linkability protections require further documentation; hidden values alone do not establish graph anonymity.','The stated objective is private, scarce and scalable digital money. No dated new-feature commitment was verified.',['https://www.mwc.mw/']],
'ghost-by-mcafee':['The listed project site describes a privacy ecosystem around proof of stake, but usable current technical evidence was insufficient.','The broad positioning is private payments; a current authoritative roadmap and delivery status could not be verified.',['https://ghostbyjohnmcafee.com/']],
'prcy-coin':['The saved listing identifies an Ethereum representation. Its transfer visibility must be distinguished from any native-chain privacy system; current native guarantees were not verified.','The listed project site could not be read successfully, so this review cannot establish current goals or a delivery schedule.',['https://prcycoin.com/']],
zero:['The listed project site could not be read successfully. A similarly named coin or related codebase cannot establish this asset’s current privacy properties.','Current project objectives and a dated roadmap could not be verified from the available source.',['https://zerocurrency.io/']],
loyal:['A current authoritative protocol description for the specific LOYAL listing was not resolved. Privacy protection, custody and transfer visibility remain unverified.','No attributable current roadmap was established; do not infer future features from the name or privacy-category listing.',[]],
'dragonx-2':['Current technical evidence for this specific DragonX listing was not resolved. Claims from other DragonX projects must not be transferred to it.','An attributable current development roadmap was not verified.',[]],
'blackcoin-3':['This BLACKCOIN listing must not be confused with legacy BlackCoin (BLK). A verified privacy protocol for this asset was not established.','No current authoritative roadmap was resolved for this exact listing.',[]],
'black-hole-2':['The BLACK HOLE listing has not been matched to sufficient authoritative protocol evidence. Similarly named DeFi or token projects are not interchangeable.','A project-specific future plan and release schedule remain unverified.',[]],
'-7':['Voidify’s provider identifier is unusual; a verified protocol specification tied to this exact asset was not established.','No attributable roadmap or dated delivery commitment was verified.',[]],
junocash:['Search surfaced shielded-payment descriptions, but an authoritative technical source tied to this exact JunoCash listing was not verified. These descriptions are not adopted as established protocol facts.','A primary-source roadmap and activation history remain unverified.',[]],
'machines-cash':['The provider-linked project site could not be read successfully. The token’s name and category do not establish confidentiality or safe custody.','A current attributable roadmap could not be verified from the listed site.',['https://www.machines.cash/']],
tritcoin:['The linked site presents a ternary key-exchange topic. That alone does not establish the listed token’s transaction privacy or quantum resistance.','The relationship between the cryptographic material, the token and a delivery roadmap remains unverified.',['https://tritcoin.vercel.app/']],
'5ive-privacy':['The listed project site could not be read successfully. No current technical specification or independent audit coverage was established.','Current objectives and delivery milestones could not be verified.',['https://5iveprivacy.com/']],
nulltrace:['The provider-linked domain redirected to unrelated content during review. It is not used as protocol evidence or linked as a trusted project source.','No current attributable roadmap was verified. The domain mismatch is an evidence gap, not proof of a particular security incident.',[]],
'poseidon-4':['This specific Poseidon listing has not been matched to sufficient authoritative documentation. The Poseidon cryptographic hash name does not prove a token implements private transfers.','No project-specific current roadmap was verified.',[]],
lethe:['The listed site was not consistently retrievable, and sufficient technical evidence to establish transfer confidentiality was not obtained.','A current authoritative roadmap and delivery status remain unverified.',['https://www.lethe.run/']],
'shady-labs':['The listed site describes privacy for an open ledger, but readable technical material was insufficient to establish how privacy is delivered or who must be trusted.','The broad positioning is privacy infrastructure. Specific future features and activation dates remain unverified.',['https://www.shady.to/']]
};
for(const [id,[privacy,goal,sources]] of Object.entries(gaps)) research[id]=entry(privacy,'Unknown protections must not be treated as active protections. Native coins, wrapped tokens, applications and network routing may expose different information.','Audit coverage, privileged controls, consensus or host-chain dependencies, and wallet custody have not been established for this listing. This is an evidence gap, not a finding that an exploit exists.',goal,'Evidence needed: an attributable technical specification, current release history, and a roadmap distinguishing shipped functionality from proposals. No delivery date is inferred from marketing or market-data classification.',sources,'Limited evidence · further verification needed');

Object.assign(research,ecosystem);

export function researchFor(coin){return research[coin.id]??entry(`Detailed privacy evidence for ${coin.name} has not yet been reviewed.`,'Category inclusion does not establish confidential transfers.','Current implementation, custody and audit coverage are unverified.','An attributable project objective has not yet been summarized.','No verified roadmap or delivery dates are available in this review.',[],'Not yet reviewed');}
export function renderResearch(coin){
 const r=researchFor(coin),el=id=>document.getElementById(id);
 for(const [id,key] of Object.entries({protocol:'privacy',privacyLimits:'limits',securityDetails:'security',goals:'goal',futurePlans:'next'}))el(id).textContent=r[key];
 el('researchStatus').textContent=r.status;
 el('researchDate').textContent=`Research checked: September 18, 2026 · Source-based summary, not a security audit.`;
 el('researchSources').replaceChildren();
 for(const url of r.sources){const a=document.createElement('a');a.href=url;a.textContent=`${new URL(url).hostname}${new URL(url).pathname==='/'?'':new URL(url).pathname} ↗`;a.target='_blank';a.rel='noopener noreferrer';el('researchSources').append(a);}
 if(!r.sources.length)el('researchSources').textContent='No usable authoritative technical source verified for this entry.';
}
